WITH base AS (SELECT *, DATE_ADD(ends_on, 3) AS ends_on_plus_3d, LAST_DAY(starts_on) AS starts_on_month_end FROM promotions WHERE channel NOT IN ('partner', 'mobile', 'store')) SELECT a.*, pr.id AS promo_id, pr.promo_code AS promotion_promo_code, pr.discount_pct AS promotion_discount_pct FROM base a LEFT JOIN promotions pr ON a.channel <=> pr.channel AND a.ends_on_plus_3d >= pr.starts_on AND a.ends_on_plus_3d < pr.ends_on + INTERVAL 30 DAYS;
